import {useState} from 'react';import {api} from '../api';
type Report={checkedAt:string;requests:number;steps:{name:string;status:string;detail:string}[]};
export function DataAcceptance(){
 const [platform,setPlatform]=useState('xiaohongshu'),[keyword,setKeyword]=useState(''),[report,setReport]=useState<Report|null>(null),[message,setMessage]=useState(''),[busy,setBusy]=useState(false);
 async function run(paid:boolean){setBusy(true);setMessage('');try{const r=paid?await api<Report>('/data-acceptance',{platform,keyword,allowPaid:true}):await api<Report|null>('/data-acceptance?platform='+platform);setReport(r);if(!r)setMessage('当前数据源与密钥尚无验收记录');}catch(e){setMessage((e as Error).message);}finally{setBusy(false);}}
 return <details className="panel"><summary>真实数据源验收</summary><p>仅验证当前业务所选 API。最多尝试 5 次请求，可能收费，仍受预算限制。不会登录账号或发送消息；无下一页会标记未验证，RedFox 异步评论可稍后复查。</p><label>平台<select value={platform} onChange={e=>{setPlatform(e.target.value);setReport(null);}}><option value="xiaohongshu">小红书</option><option value="douyin">抖音</option></select></label><label>业务关键词<input maxLength={100} value={keyword} onChange={e=>setKeyword(e.target.value)}/></label><button className="btn" disabled={busy} onClick={()=>void run(false)}>查看上次验收</button><button className="btn" disabled={busy||!keyword.trim()} onClick={()=>{if(confirm('此次会调用已配置的付费 API，最多 5 次请求。继续？'))void run(true);}}>验收搜索、详情与评论（可能收费）</button><p role="status">{message}</p>{report&&<><p>{new Date(report.checkedAt).toLocaleString()} · 请求 {report.requests} 次</p>{report.steps.map((s,i)=><p key={i}>{s.name}：{({passed:'通过',unverified:'未验证',unsupported:'不支持',pending:'等待供应商完成',failed:'失败'} as Record<string,string>)[s.status]} · {s.detail}</p>)}</>}</details>;
}
